-- Regions (reference regions only hold another region's external contributors)
insert into specialization.regions as t (id, label, heading, sort_order, status, body_map_keys, entry_label, node_for_body_map_key) values
  ($$forearm$$, $$Forearms$$, $$Forearm specialization$$, 10, $$production$$, array[$$forearms$$, $$brachioradialis$$], $$Explore forearm coverage$$, $${"brachioradialis":"forearm.br"}$$::jsonb),
  ($$upper_arm$$, $$Upper arm$$, null, 0, $$reference$$, array[]::text[], null, $${}$$::jsonb)
on conflict (id) do update set label = excluded.label, heading = excluded.heading, sort_order = excluded.sort_order, status = excluded.status, body_map_keys = excluded.body_map_keys, entry_label = excluded.entry_label, node_for_body_map_key = excluded.node_for_body_map_key
  where (t.label, t.heading, t.sort_order, t.status, t.body_map_keys, t.entry_label, t.node_for_body_map_key) is distinct from (excluded.label, excluded.heading, excluded.sort_order, excluded.status, excluded.body_map_keys, excluded.entry_label, excluded.node_for_body_map_key);

-- Joint actions
insert into specialization.actions as t (id, joint, label, plain_description, sort_order) values
  ($$elbow.extension$$, $$Elbow$$, $$Elbow extension$$, $$Straightens the elbow.$$, 1),
  ($$elbow.flexion$$, $$Elbow$$, $$Elbow flexion$$, $$Bends the elbow, bringing the hand toward the shoulder.$$, 0),
  ($$fingers.dip_flexion$$, $$Fingertip joints (DIP)$$, $$Fingertip flexion$$, $$Bends the four fingers at their end joints, curling the fingertips.$$, 10),
  ($$fingers.extension$$, $$Finger knuckles (MCP)$$, $$Finger extension$$, $$Straightens the four fingers, mainly at the knuckles.$$, 11),
  ($$fingers.mcp_flexion$$, $$Finger knuckles (MCP)$$, $$Knuckle flexion$$, $$Bends the four fingers at the knuckles.$$, 8),
  ($$fingers.pip_flexion$$, $$Finger middle joints (PIP)$$, $$Middle-joint flexion$$, $$Bends the four fingers at their middle joints.$$, 9),
  ($$forearm.distal_radioulnar_stabilization$$, $$Distal radioulnar joint$$, $$Steadies the forearm bones at the wrist$$, $$Helps keep the ends of the two forearm bones pressed together near the wrist, including while the forearm turns.$$, 19),
  ($$forearm.pronation$$, $$Forearm (radioulnar joints)$$, $$Pronation$$, $$Turns the forearm so the palm faces down (with the elbow bent).$$, 2),
  ($$forearm.supination$$, $$Forearm (radioulnar joints)$$, $$Supination$$, $$Turns the forearm so the palm faces up (with the elbow bent).$$, 3),
  ($$hand.palmar_aponeurosis_tension$$, $$Palm$$, $$Palmar fascia tension$$, $$Tenses the sheet of connective tissue under the skin of the palm.$$, 18),
  ($$index_finger.extension$$, $$Index finger$$, $$Index-finger extension$$, $$Straightens the index finger on its own, as when pointing.$$, 13),
  ($$little_finger.extension$$, $$Little finger$$, $$Little-finger extension$$, $$Straightens the little finger on its own.$$, 12),
  ($$thumb.cmc_abduction$$, $$Thumb base (CMC)$$, $$Thumb abduction$$, $$Moves the thumb out from the hand at its base, away from the index finger.$$, 15),
  ($$thumb.ip_extension$$, $$Thumb tip (IP)$$, $$Thumb-tip extension$$, $$Straightens the tip of the thumb.$$, 17),
  ($$thumb.ip_flexion$$, $$Thumb tip (IP)$$, $$Thumb-tip flexion$$, $$Bends the tip of the thumb.$$, 14),
  ($$thumb.mcp_extension$$, $$Thumb knuckle (MCP)$$, $$Thumb-knuckle extension$$, $$Straightens the thumb at its knuckle.$$, 16),
  ($$wrist.extension$$, $$Wrist$$, $$Wrist extension$$, $$Bends the wrist back, toward the back of the hand.$$, 5),
  ($$wrist.flexion$$, $$Wrist$$, $$Wrist flexion$$, $$Bends the wrist toward the palm.$$, 4),
  ($$wrist.radial_deviation$$, $$Wrist$$, $$Radial deviation$$, $$Tilts the hand toward the thumb side.$$, 6),
  ($$wrist.ulnar_deviation$$, $$Wrist$$, $$Ulnar deviation$$, $$Tilts the hand toward the pinky side.$$, 7)
on conflict (id) do update set joint = excluded.joint, label = excluded.label, plain_description = excluded.plain_description, sort_order = excluded.sort_order
  where (t.joint, t.label, t.plain_description, t.sort_order) is distinct from (excluded.joint, excluded.label, excluded.plain_description, excluded.sort_order);

-- Anatomy nodes, parents first
insert into specialization.nodes as t (id, region_id, parent_id, kind, role, name, short_name, aliases, layer, surface_visibility, status, catalog_muscle_key, database_muscle, border, location, what_it_does, shape_note, caveats, sort_order) values
  ($$forearm.anterior$$, $$forearm$$, null, $$compartment$$, $$group$$, $$Anterior (flexor-pronator) compartment$$, $$Palm side$$, array[$$flexor compartment$$, $$forearm flexors$$], $$mixed$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$both$$, $$Palm side of the forearm, in a surface, a middle and a deep layer from the elbow to the wrist.$$, $$Bends the wrist and the fingers and turns the palm down.$$, $$Together these muscles make up most of the palm-side fullness of the forearm. Which muscle shapes which part of that outline cannot be read from the surface. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$A group, not a muscle: work is counted for the individual muscles inside it.$$], 0),
  ($$forearm.posterior$$, $$forearm$$, null, $$compartment$$, $$group$$, $$Posterior (extensor-supinator) compartment$$, $$Back side$$, array[$$extensor compartment$$, $$forearm extensors$$], $$mixed$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$both$$, $$Back of the forearm and its thumb-side edge, in a surface layer and a deep layer from the elbow to the wrist.$$, $$Straightens the wrist, the fingers and the thumb and turns the palm up. The brachioradialis, also in this group, bends the elbow.$$, $$Makes up the back of the forearm and, through the brachioradialis and the thumb-side wrist extensors, the thumb-side outline near the elbow. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$A group, not a muscle: work is counted for the individual muscles inside it.$$], 1),
  ($$upper_arm.biceps$$, $$upper_arm$$, null, $$muscle$$, $$external$$, $$Biceps brachii$$, $$Biceps$$, array[$$biceps$$], $$surface$$, $$clear$$, $$reviewed$$, $$biceps$$, $$biceps_brachii$$, null, $$Front of the upper arm, crossing the elbow to the radius.$$, $$Bends your elbow and turns your palm up; with the elbow bent it is the strongest palm-up muscle.$$, $$Shapes the front of the upper arm. It is an upper-arm muscle and does not add forearm size.$$, array[$$Shown only as another muscle that curls and palm-up turning load; not a forearm target.$$], 22),
  ($$upper_arm.brachialis$$, $$upper_arm$$, null, $$muscle$$, $$external$$, $$Brachialis$$, $$Brachialis$$, array[$$brachialis$$], $$deep$$, $$partial$$, $$reviewed$$, $$brachialis$$, $$brachialis$$, null, $$Front of the lower upper arm, under the biceps, crossing the elbow to the ulna.$$, $$Bends your elbow, whichever way the palm faces. It does not turn the forearm.$$, $$Mostly covered by the biceps; may show at the sides of the lower upper arm. It is not a forearm muscle.$$, array[$$Shown only as another muscle that curls load; not a forearm target.$$], 23),
  ($$forearm.br$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Brachioradialis$$, $$BR$$, array[$$brachioradialis$$], $$surface$$, $$clear$$, $$reviewed$$, $$forearms$$, $$brachioradialis$$, $$radial$$, $$Thumb side of the forearm, from just above the elbow to the wrist; the outermost muscle on that edge.$$, $$Bends your elbow. It works whichever way the palm faces; anatomy texts describe it as strongest with the thumb pointing up.$$, $$Contributes to the thumb-side contour of the upper forearm, the bulge just below the elbow. It does not bend the wrist. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$Studies disagree on whether turning the palm up, sideways or down changes how hard it works in a curl.$$, $$From a fully palm-up or palm-down start it also turns the forearm back toward thumb-up; that is not counted as a separate action here.$$], 2),
  ($$forearm.fcr$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Flexor carpi radialis$$, $$FCR$$, array[$$FCR$$, $$radial wrist flexor$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$radial$$, $$Palm side, surface layer, running at a slant from the pinky side of the elbow to the thumb side of the wrist.$$, $$Bends your wrist toward the palm and toward the thumb side.$$, $$May contribute to the palm-side contour toward the thumb side, between the elbow crease and mid-forearm. It is not the whole thumb-side width: the brachioradialis forms that edge. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$Its tendon is easy to see at the wrist; a visible tendon is not muscle size.$$], 3),
  ($$forearm.fcu$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Flexor carpi ulnaris$$, $$FCU$$, array[$$FCU$$, $$ulnar wrist flexor$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$ulnar$$, $$Palm side, surface layer, along the pinky-side edge from the elbow to the wrist.$$, $$Bends your wrist toward the palm and toward the pinky side.$$, $$Contributes to the palm-side contour along the pinky side (ulnar). Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[]::text[], 4),
  ($$forearm.pl$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Palmaris longus$$, $$PL$$, array[$$PL$$], $$surface$$, $$variable$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$central$$, $$Palm side, surface layer, down the middle: a short belly near the elbow and a long tendon to the palm.$$, $$Tenses the sheet of connective tissue in the palm and gives a little help bending the wrist.$$, $$Small belly and long tendon, and missing in some people, so it is not a major driver of forearm width. Visible shape depends far more on the muscles around it.$$, array[$$Absent on one or both sides in some people; how often varies widely between populations.$$, $$Its absence has not been shown to reduce grip strength.$$], 5),
  ($$forearm.fds$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Flexor digitorum superficialis$$, $$FDS$$, array[$$FDS$$, $$superficial finger flexor$$, $$flexor digitorum sublimis$$], $$intermediate$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$central$$, $$Palm side, middle layer: under the surface wrist flexors and over the deep finger flexor.$$, $$Bends your four fingers at their middle joints, and helps bend the knuckles and the wrist. Each finger has its own part of the muscle, but the parts do not work fully apart.$$, $$May add to the general fullness of the palm side of the forearm. It lies under other muscles, so it has no separately visible outline.$$, array[$$Grip and finger-curl work loads it together with the deep finger flexor (FDP); how the work splits between them is not known.$$], 6),
  ($$forearm.fdp$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Flexor digitorum profundus$$, $$FDP$$, array[$$FDP$$, $$deep finger flexor$$], $$deep$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$ulnar$$, $$Palm side, deep layer, against the ulna on the pinky side and under the other finger flexors.$$, $$Bends your fingertips: it is the only muscle that bends the end joints of the four fingers. It also helps bend the middle joints, the knuckles and the wrist.$$, $$Deep bulk under the palm-side muscles. It may add to overall palm-side thickness but has little or no separately visible surface contour, so it is not drawn as a surface stripe.$$, array[$$Grip and finger-curl work loads it together with FDS; how the work splits between them is not known.$$], 7),
  ($$forearm.fpl$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Flexor pollicis longus$$, $$FPL$$, array[$$FPL$$, $$long thumb flexor$$], $$deep$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, $$forearm_flexors$$, $$radial$$, $$Palm side, deep layer, on the thumb side against the radius.$$, $$Bends the tip of your thumb, and helps bend the thumb at its knuckle. No other muscle bends the thumb tip.$$, $$Deep tissue on the thumb side of the palm side, close to the bone; little or no separately visible contour.$$, array[$$Hard to feel through the skin because it lies under the other flexors.$$], 8),
  ($$forearm.pt$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Pronator teres$$, $$PT$$, array[$$PT$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, null, $$central$$, $$Palm side just below the elbow, surface layer, slanting from the pinky side of the elbow to the middle of the radius on the thumb side.$$, $$Turns your palm down, and gives a little help bending the elbow.$$, $$May contribute to the slanted palm-side contour just below the elbow crease, where it forms the pinky-side edge of the hollow in front of the elbow. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$Both pronators turn the palm down, so palm-down work loads it together with the pronator quadratus.$$], 9),
  ($$forearm.pq$$, $$forearm$$, $$forearm.anterior$$, $$muscle$$, $$target$$, $$Pronator quadratus$$, $$PQ$$, array[$$PQ$$], $$deep$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, null, $$both$$, $$Palm side, deepest layer: a flat, square muscle on the two forearm bones just above the wrist.$$, $$Turns your palm down, and helps hold the two forearm bones together near the wrist.$$, $$Deep and close to the bones near the wrist, under the flexor tendons; little or no direct surface definition.$$, array[$$Both pronators turn the palm down, so palm-down work loads it together with the pronator teres.$$], 10),
  ($$forearm.ecrl$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor carpi radialis longus$$, $$ECRL$$, array[$$ECRL$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$radial$$, $$Back of the forearm on the thumb side, starting just above the elbow beside the brachioradialis.$$, $$Bends your wrist back and toward the thumb side.$$, $$May contribute to the contour on the back and thumb side of the forearm near the elbow. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$Ordinary exercises cannot train it apart from ECRB; the two are counted together in practice.$$], 11),
  ($$forearm.ecrb$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor carpi radialis brevis$$, $$ECRB$$, array[$$ECRB$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$radial$$, $$Back of the forearm on the thumb side, beside and partly under ECRL.$$, $$Bends your wrist back and toward the thumb side.$$, $$Part of the extensor mass on the back and thumb side of the forearm. Partly covered by ECRL, so its own outline is only partly visible. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[$$Ordinary exercises cannot train it apart from ECRL; the two are counted together in practice.$$, $$In one study it was more active in wrist-extension holds with the palm turned down. That is short-term muscle activity, not growth.$$], 12),
  ($$forearm.ecu$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor carpi ulnaris$$, $$ECU$$, array[$$ECU$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$ulnar$$, $$Back of the forearm, surface layer, along the pinky-side edge from the elbow to the wrist.$$, $$Bends your wrist back and toward the pinky side.$$, $$May contribute to the contour along the back of the forearm on the pinky side. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[]::text[], 13),
  ($$forearm.ed$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor digitorum$$, $$ED$$, array[$$ED$$, $$extensor digitorum communis$$, $$EDC$$], $$surface$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$central$$, $$Back of the forearm, surface layer, down the middle; it splits into four tendons that run to the fingers.$$, $$Straightens your four fingers, mainly at the knuckles, and helps bend the wrist back.$$, $$May contribute to the central mass on the back of the forearm. Its tendons on the back of the hand are tendon, not muscle bulk. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, array[]::text[], 14),
  ($$forearm.edm$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor digiti minimi$$, $$EDM$$, array[$$EDM$$, $$extensor digiti quinti$$], $$surface$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$ulnar$$, $$Back of the forearm, surface layer: a thin muscle on the pinky side of the extensor digitorum.$$, $$Straightens your little finger, on its own or with the other fingers.$$, $$Small, and joined to the extensor digitorum near the elbow; not a major independent driver of forearm width.$$, array[$$Some anatomists treat it as the pinky-side part of the extensor digitorum.$$], 15),
  ($$forearm.ei$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor indicis$$, $$EI$$, array[$$EI$$, $$extensor indicis proprius$$], $$deep$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$central$$, $$Back of the forearm, deep layer near the wrist, arising on the pinky side; its tendon runs to the index finger.$$, $$Straightens your index finger, which lets it point on its own.$$, $$Small and deep near the wrist; little or no separately visible contour.$$, array[]::text[], 16),
  ($$forearm.apl$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Abductor pollicis longus$$, $$APL$$, array[$$APL$$], $$deep$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$radial$$, $$Back of the forearm, deep layer, coming to the surface on the thumb side above the wrist on its way to the base of the thumb.$$, $$Moves your thumb out from the hand at its base, away from the index finger, and helps straighten it there.$$, $$Mostly deep, with little separately visible contour. Near the wrist its tendon, with EPB's, forms the thumb-side edge of the hollow at the base of the thumb; a visible tendon there is not muscle size.$$, array[$$References disagree about a small effect at the wrist, so no wrist action is counted for it here.$$], 17),
  ($$forearm.epb$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor pollicis brevis$$, $$EPB$$, array[$$EPB$$], $$deep$$, $$partial$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$radial$$, $$Back of the forearm, deep layer near the wrist on the thumb side, beside APL.$$, $$Straightens your thumb at its knuckle, and helps straighten it at its base.$$, $$Small and deep, with little separately visible contour. Its tendon at the base of the thumb can be easy to see; that is tendon, not muscle size.$$, array[$$Where its tendon attaches varies a good deal between people.$$], 18),
  ($$forearm.epl$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Extensor pollicis longus$$, $$EPL$$, array[$$EPL$$], $$deep$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, $$forearm_extensors$$, $$central$$, $$Back of the forearm, deep layer in the middle; a long tendon bends around a bony bump on the back of the radius to reach the thumb tip.$$, $$Straightens the tip of your thumb, and helps straighten the thumb at its knuckle.$$, $$Deep muscle with little or no separately visible contour. Its long tendon forms the pinky-side edge of the hollow at the base of the thumb; a visible tendon is not muscle size.$$, array[]::text[], 19),
  ($$forearm.supinator$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$target$$, $$Supinator$$, $$SUP$$, array[$$supinator$$], $$deep$$, $$not_distinct$$, $$reviewed$$, $$forearms$$, null, $$radial$$, $$Just below the elbow on the back and thumb side, deep layer, wrapped around the top of the radius.$$, $$Turns your palm up.$$, $$Deep near the elbow, under the surface extensors; not directly visible in an ordinary surface view.$$, array[$$With the elbow bent the biceps is the stronger palm-up muscle, so palm-up work with a bent elbow is not supinator-only.$$], 20),
  ($$forearm.anconeus$$, $$forearm$$, $$forearm.posterior$$, $$muscle$$, $$adjacent$$, $$Anconeus$$, $$ANC$$, array[$$anconeus$$], $$surface$$, $$partial$$, $$reviewed$$, $$triceps$$, null, $$ulnar$$, $$Back of the elbow: a small triangle from the thumb-side bony knob of the upper-arm bone to the point of the elbow.$$, $$Helps straighten your elbow and steadies the joint; the triceps does most of the straightening.$$, $$Small; may add to the contour at the back of the elbow. It is not a forearm growth target.$$, array[$$Shown beside the forearm muscles because of where it sits; forearm specialization does not target it.$$], 21)
on conflict (id) do update set region_id = excluded.region_id, parent_id = excluded.parent_id, kind = excluded.kind, role = excluded.role, name = excluded.name, short_name = excluded.short_name, aliases = excluded.aliases, layer = excluded.layer, surface_visibility = excluded.surface_visibility, status = excluded.status, catalog_muscle_key = excluded.catalog_muscle_key, database_muscle = excluded.database_muscle, border = excluded.border, location = excluded.location, what_it_does = excluded.what_it_does, shape_note = excluded.shape_note, caveats = excluded.caveats, sort_order = excluded.sort_order
  where (t.region_id, t.parent_id, t.kind, t.role, t.name, t.short_name, t.aliases, t.layer, t.surface_visibility, t.status, t.catalog_muscle_key, t.database_muscle, t.border, t.location, t.what_it_does, t.shape_note, t.caveats, t.sort_order) is distinct from (excluded.region_id, excluded.parent_id, excluded.kind, excluded.role, excluded.name, excluded.short_name, excluded.aliases, excluded.layer, excluded.surface_visibility, excluded.status, excluded.catalog_muscle_key, excluded.database_muscle, excluded.border, excluded.location, excluded.what_it_does, excluded.shape_note, excluded.caveats, excluded.sort_order);

-- Sources
insert into specialization.sources as t (source_key, url, title, doi, evidence_type, retrieved_on, notes) values
  ($$A1$$, $$https://www.ncbi.nlm.nih.gov/books/NBK526110/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Forearm Brachioradialis Muscle (Lung, Ekblad, Bisogno)$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: active in elbow flexion with the forearm supinated, neutral or pronated; pronates from supination and supinates from pronation; one of two extensor-compartment muscles that do not cross the wrist; sits in the mobile wad with ECRL and ECRB; radial nerve. Updated 30 Jan 2024.$$),
  ($$A10$$, $$https://doi.org/10.1002/ca.22289$$, $$Yammine, Clinical prevalence of palmaris longus agenesis: a systematic review and meta-analysis (Clinical Anatomy 26(6):709–718, 2013)$$, $$10.1002/ca.22289$$, $$systematic_review$$, $$2026-10-16$$, $$Checked via web-search results (abstract): 26 clinical prevalence studies; the pooled absence rate was higher than the commonly quoted figure and varied strongly by population, lowest in East and South-East African subgroups and highest in Arab Middle Eastern groups; no significant sex difference. Clinical examination studies only.$$),
  ($$A11$$, $$https://radiopaedia.org/articles/23240$$, $$Radiopaedia: palmaris longus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: absence frequency differs between populations (lower in Asian and African-American groups than in white and Hispanic groups).$$),
  ($$A12$$, $$https://www.ncbi.nlm.nih.gov/books/NBK539723/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Hand Flexor Digitorum Superficialis Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: the largest extrinsic forearm flexor; forms the intermediate layer between the superficial and deep groups; four digital components, each with its own tendon; the primary flexor of the PIP joints, also assisting MCP flexion; runs superficial to FDP and FPL.$$),
  ($$A13$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/flexor-digitorum-superficialis/20893$$, $$Elsevier Complete Anatomy, Quick Facts: flexor digitorum superficialis$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: flexes the middle phalanges, assists flexion at the MCP joints and assists flexion of the hand at the wrist.$$),
  ($$A14$$, $$https://pubmed.ncbi.nlm.nih.gov/30252302/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Hand Flexor Digitorum Profundus Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: flexes the MCP and DIP joints of the medial four digits and is the only muscle that flexes the DIP joints; DIP flexion depends on wrist position and its tension falls when the wrist is fully flexed; tendons insert deep to the FDS tendons.$$),
  ($$A15$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/flexor-digitorum-profundus/18692$$, $$Elsevier Complete Anatomy, Quick Facts: flexor digitorum profundus$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: DIP flexion is the primary action, with secondary roles at the PIP and MCP joints and the wrist; the index-finger part can flex on its own.$$),
  ($$A16$$, $$https://pubmed.ncbi.nlm.nih.gov/31408520/$$, $$Fox, Oliver, Nguyen, Hentz and Curtin, video electromyography of extrinsic and intrinsic finger flexors during grasp (Orthopedics 42(6):e555–e558, 2019)$$, null, $$emg$$, $$2026-10-16$$, $$Checked via web-search results (abstract on a Stanford Health Care page, and a 2014 poster by the same group): light fist formation mainly used FDP with either FDS or the intrinsics; FDS and the intrinsics were recruited in every tight fist, in an order that differed between patients; FDP described as the workhorse of composite fist formation. Prospective cohort including injured hands. The exact article title was not confirmed.$$),
  ($$A17$$, $$https://www.statpearls.com/articlelibrary/viewarticle/36137/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Hand Flexor Pollicis Longus Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (introduction and start of the structure section): one of three deep flexors of the volar compartment; the main thumb flexor, acting at the MCP and IP joints; courses along the radial aspect of the volar forearm, deep and radial to the radial head of FDS; anterior interosseous nerve.$$),
  ($$A18$$, $$https://radiopaedia.org/articles/flexor-pollicis-longus$$, $$Radiopaedia: flexor pollicis longus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: action is flexion of the interphalangeal joint of the thumb; anterior interosseous nerve.$$),
  ($$A19$$, $$https://www.kenhub.com/en/library/anatomy/flexor-pollicis-longus-muscle$$, $$Kenhub: flexor pollicis longus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: the only muscle that flexes the interphalangeal joint of the thumb; absent in a small part of the population and can blend with neighbouring flexors.$$),
  ($$A2$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/brachioradialis-muscle/23633$$, $$Elsevier Complete Anatomy, Quick Facts: brachioradialis$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: primarily flexes the elbow and is strongest in mid-pronation (citing Gray's Anatomy); its medial margin is the lateral boundary of the cubital fossa.$$),
  ($$A20$$, $$https://www.kenhub.com/en/library/anatomy/the-deep-flexors-of-the-forearm$$, $$Kenhub: deep anterior forearm muscles$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: FDP, FPL and pronator quadratus form the deep group; they run under FDS, very close to the radius and ulna, and are difficult to palpate.$$),
  ($$A21$$, $$https://www.statpearls.com/point-of-care/145103$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Pronator Teres$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: main action is pronation, with a small role in elbow flexion; humeral and ulnar heads with the median nerve between them; inserts on the lateral midshaft of the radius below the supinator; its lateral edge forms the medial border of the cubital fossa. The search reported this article's Bookshelf id as NBK580564; not opened directly.$$),
  ($$A22$$, $$https://www.kenhub.com/en/library/anatomy/pronator-teres-muscle$$, $$Kenhub: pronator teres muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: humeral head from the medial supracondylar ridge, ulnar head from the coronoid process; inserts on the lateral surface of the radius distal to the supinator; actions are forearm pronation and elbow flexion; median nerve.$$),
  ($$A23$$, $$https://radiopaedia.org/articles/pronator-quadratus$$, $$Radiopaedia: pronator quadratus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: the most distal muscle of the deepest layer of the anterior compartment; from the distal quarter of the ulna to the distal quarter of the radius; pronates the forearm; anterior interosseous nerve.$$),
  ($$A24$$, $$https://www.kenhub.com/en/library/anatomy/pronator-quadratus-muscle$$, $$Kenhub: pronator quadratus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: flat, short, quadrilateral muscle; the deepest muscle of the anterior compartment; forearm pronation; anterior interosseous branch of the median nerve.$$),
  ($$A25$$, $$https://heibib.ub.uni-heidelberg.de/search/Record/1693802481$$, $$Spies et al., Anatomie und Biomechanik des distalen Radioulnargelenks (Anatomy and biomechanics of the distal radioulnar joint), Der Orthopäde 47(8):621–627, 2018$$, null, $$biomechanics$$, $$2026-10-16$$, $$Checked via web-search results (library record abstract): the triangular fibrocartilage complex is the main stabiliser; pronator quadratus is the relevant dynamic stabiliser of the DRUJ, and its contraction prevents diastasis of the joint. German-language review.$$),
  ($$A26$$, $$https://litfl.com/wp-content/uploads/2019/06/382.pdf$$, $$Tsai and Paksima, review of the distal radioulnar joint (2009; PDF hosted by LITFL)$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: ECU and pronator quadratus are dynamic stabilisers of the DRUJ; the deep head of pronator quadratus is the prime stabiliser while the superficial head is the more powerful pronator. Journal details were not confirmed by the search.$$),
  ($$A27$$, $$https://www.kenhub.com/en/library/anatomy/extensor-carpi-radialis-longus-muscle$$, $$Kenhub: extensor carpi radialis longus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: inserts on the base of the second metacarpal; extends and abducts (radially deviates) the hand at the wrist; radial nerve.$$),
  ($$A28$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/extensor-carpi-radialis-longus/22064$$, $$Elsevier Complete Anatomy, Quick Facts: extensor carpi radialis longus$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: extends the hand at the wrist and abducts it at the radiocarpal and midcarpal joints.$$),
  ($$A29$$, $$https://www.ncbi.nlm.nih.gov/books/NBK539719/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Forearm Extensor Carpi Radialis Brevis Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: posterior superficial compartment; the prime dorsiflexor of the wrist; works with ECRL to extend and abduct the wrist; shorter than ECRL and partly covered by it; inserts on the base of the third metacarpal. Updated 28 Aug 2023.$$),
  ($$A3$$, $$https://www.kenhub.com/en/library/anatomy/brachioradialis-muscle$$, $$Kenhub: brachioradialis muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: the most superficial muscle on the radial aspect of the forearm, palpable as the fleshy prominence in the upper half of the lateral forearm with the elbow flexed and the forearm semi-pronated.$$),
  ($$A30$$, $$https://pubmed.ncbi.nlm.nih.gov/10969198/$$, $$A new technique for the selective recording of extensor carpi radialis longus and brevis (Journal of Electromyography and Kinesiology 10(4):249–253, 2000)$$, null, $$emg$$, $$2026-10-16$$, $$Checked via web-search results (abstract): standard EMG texts held that ECRL and ECRB activity cannot be distinguished even with intramuscular electrodes; the authors placed fine-wire electrodes from cadaver measurements (10 specimens) and reported differentiated recordings in three volunteers. A methods paper, not a training study.$$),
  ($$A31$$, $$https://www.statpearls.com/point-of-care/36165$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Forearm Extensor Carpi Ulnaris Muscle (Sawyer, Sajjad, Tadi)$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: posterior forearm muscle that primarily extends and adducts the wrist, with ECRL and ECRB for extension and with FCU for adduction; humeral and ulnar heads; inserts on the dorsal base of the fifth metacarpal via the sixth extensor compartment; posterior interosseous nerve.$$),
  ($$A32$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/extensor-digitorum/22591$$, $$Elsevier Complete Anatomy, Quick Facts: extensor digitorum$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: extends the proximal phalanges at the MCP joints and the fingers at the interphalangeal joints; assists extension of the hand at the wrist.$$),
  ($$A33$$, $$https://www.kenhub.com/en/library/anatomy/extensor-digitorum-muscle$$, $$Kenhub: extensor digitorum muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: also participates in wrist extension; its belly ends in four tendons about a third of the way down the forearm, passing under the extensor retinaculum to digits 2–5.$$),
  ($$A34$$, $$https://www.ncbi.nlm.nih.gov/books/NBK534805/$$, $$StatPearls: wrist and finger extensor muscles (NBK534805)$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: extensor digitorum communis extends the index, middle, ring and little fingers; extensor indicis proprius independently extends the index finger; extensor digiti minimi independently extends the little finger. The article's exact title was not shown in the results (another site cites it as Wrist Extensor Muscles).$$),
  ($$A35$$, $$https://www.kenhub.com/en/library/anatomy/extensor-digiti-minimi-muscle$$, $$Kenhub: extensor digiti minimi muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: long, thin muscle of the superficial extensor group; proximal fibres usually fused with extensor digitorum, separate from about mid-forearm, just medial to it; extends the fifth digit at the MCP joint; posterior interosseous nerve.$$),
  ($$A36$$, $$https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/$$, $$University of Arkansas for Medical Sciences: muscles of the upper limb$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: extensor digiti minimi inserts into the extensor expansion of the fifth digit, and some anatomists regard it as the ulnar-most part of extensor digitorum; extensor indicis arises from the distal posterior ulna and interosseous membrane, joins the index tendon of extensor digitorum and extends the index finger.$$),
  ($$A37$$, $$https://www.kenhub.com/en/library/anatomy/extensor-indicis-muscle$$, $$Kenhub: extensor indicis muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: narrow, elongated deep extensor of the posterior compartment; extends the index finger at the MCP and interphalangeal joints, letting it extend on its own; weaker wrist-extension effect; posterior interosseous nerve.$$),
  ($$A38$$, $$https://anatomy.ttuhscep.edu/anatomytables/muscles_upperlimb.html$$, $$Texas Tech University Health Sciences Center El Paso: muscles of the upper limb, listed alphabetically$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (only some rows were shown): abductor pollicis longus abducts the thumb at the carpometacarpal joint; the tendons of abductor pollicis longus and extensor pollicis brevis form the lateral border of the anatomical snuffbox; anconeus runs from the lateral epicondyle to the olecranon and upper ulna and extends the forearm.$$),
  ($$A39$$, $$https://www.kenhub.com/en/library/anatomy/abductor-pollicis-longus-muscle$$, $$Kenhub: abductor pollicis longus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: abducts and extends the thumb at the carpometacarpal joint; the English article also lists extension of the hand at the wrist, while the German article and video describe radial deviation.$$),
  ($$A4$$, $$https://pmc.ncbi.nlm.nih.gov/articles/PMC4526813/$$, $$Kleiber, Kunz and Disselhorst-Klug, Muscular coordination of biceps brachii and brachioradialis in elbow flexion with respect to hand position (Frontiers in Physiology, 2015)$$, $$10.3389/fphys.2015.00215$$, $$emg$$, $$2026-10-16$$, $$Checked via web-search results (abstract): surface EMG, 16 healthy subjects, single elbow flexions at 20°/s with the hand pronated, neutral and supinated. Brachioradialis contribution differed significantly with the hand pronated compared with supinated and neutral; biceps activity did not change. Acute activity, not growth.$$),
  ($$A40$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/abductor-pollicis-longus/21696$$, $$Elsevier Complete Anatomy, Quick Facts: abductor pollicis longus$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: abducts and extends the thumb at the first carpometacarpal joint; no wrist action listed.$$),
  ($$A41$$, $$https://www.kenhub.com/en/library/anatomy/extensor-pollicis-brevis-muscle$$, $$Kenhub: extensor pollicis brevis muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: small, deep forearm muscle; extends the thumb at the carpometacarpal and MCP joints; with the abductor pollicis longus tendon forms the lateral border of the anatomical snuffbox; posterior interosseous nerve.$$),
  ($$A42$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/extensor-pollicis-brevis/22487$$, $$Elsevier Complete Anatomy, Quick Facts: extensor pollicis brevis$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: extends the proximal phalanx of the thumb at the first MCP joint and the first metacarpal at the first carpometacarpal joint; inserts on the dorsal base of the proximal phalanx.$$),
  ($$A43$$, $$https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3701420/$$, $$Jabir et al., The Extensor Pollicis Brevis: A Review of Its Anatomy and Variations (Eplasty)$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: textbook descriptions of the EPB tendon disagree with published anatomical studies; in one cadaver study only a quarter of tendons inserted in the conventional way, into the base of the proximal phalanx.$$),
  ($$A44$$, $$https://www.statpearls.com/point-of-care/36135$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Hand Extensor Pollicis Longus Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: thumb extensor at the MCP and IP joints (with some adduction); arises from the middle third of the posterior ulna, passes over Lister's tubercle and is the only occupant of the third extensor compartment; its tendon is the ulnar boundary of the anatomical snuffbox; posterior interosseous nerve. Updated 21 Dec 2022.$$),
  ($$A45$$, $$https://www.kenhub.com/en/library/anatomy/extensor-pollicis-longus-muscle$$, $$Kenhub: extensor pollicis longus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: main action is thumb extension at the MCP and interphalangeal joints, with a weak contribution to wrist extension.$$),
  ($$A46$$, $$https://www.kenhub.com/en/library/anatomy/supinator-muscle$$, $$Kenhub: supinator muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: spiral muscle of the deep part of the posterior compartment that wraps around the proximal radius and rotates it laterally (supination); found deep in the forearm, superficial only to the radius and ulna; posterior interosseous nerve.$$),
  ($$A47$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/supinator/21216$$, $$Elsevier Complete Anatomy, Quick Facts: supinator$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: supinates the forearm at the radioulnar joints; tested against resistance with the elbow extended, which keeps biceps brachii from contributing to supination.$$),
  ($$A48$$, $$https://www.kenhub.com/en/library/anatomy/anconeus-muscle$$, $$Kenhub: anconeus muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: small triangular muscle at the back of the elbow from the lateral epicondyle to the lateral olecranon; helps extend the forearm at the elbow and helps stabilise the joint; some authors consider it a continuation of triceps; radial nerve.$$),
  ($$A49$$, $$https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-upper-limb/anconeus-muscle/20503$$, $$Elsevier Complete Anatomy, Quick Facts: anconeus$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: posterior and superficial to the elbow joint; extends the forearm at the elbow joint.$$),
  ($$A5$$, $$https://scholars.uky.edu/en/publications/the-function-of-brachioradialis/$$, $$The function of brachioradialis (University of Kentucky publication record)$$, null, $$emg$$, $$2026-10-16$$, $$Checked via web-search results (record summary): fine-wire EMG in 10 healthy volunteers flexing the elbow with the forearm neutral, pronated or supinated at several loads found no difference in activation between the three positions; activity was higher when lifting than lowering. Authors and journal were not confirmed by the search.$$),
  ($$A50$$, $$https://www.ncbi.nlm.nih.gov/books/NBK519538/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Biceps Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (introduction): a forearm flexor when the elbow is extended that becomes the forearm's most powerful supinator when the elbow is flexed; inserts on the radial tuberosity; musculocutaneous nerve.$$),
  ($$A51$$, $$https://www.ncbi.nlm.nih.gov/books/NBK551630/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Brachialis Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (introduction): flexes the elbow in all physiological positions and is considered a pure flexor; no supination or pronation; lies in the anteroinferior arm, deeper than the biceps; inserts on the ulnar tuberosity.$$),
  ($$A52$$, $$https://www.ncbi.nlm.nih.gov/books/NBK536975/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Forearm Muscles$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (introduction and structure): an anterior (flexor) and a posterior (extensor) compartment holding about twenty muscles, each subdivided into superficial and deep parts. Updated 5 Jun 2023.$$),
  ($$A53$$, $$https://www.kenhub.com/en/library/anatomy/the-superficial-flexors-of-the-forearm$$, $$Kenhub: superficial anterior forearm muscles$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: groups pronator teres, flexor carpi radialis, palmaris longus, flexor carpi ulnaris and flexor digitorum superficialis as superficial anterior muscles sharing the common flexor origin on the medial epicondyle (a teaching source places FDS in a middle layer beneath the first four).$$),
  ($$A54$$, $$https://www.kenhub.com/en/library/anatomy/the-superficial-extensors-of-the-forearm$$, $$Kenhub: superficial extensors of the forearm$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: brachioradialis, ECRL, ECRB, extensor digitorum, extensor digiti minimi and ECU form the superficial posterior group, mostly from the common extensor origin on the lateral epicondyle; anconeus is discussed with the arm muscles.$$),
  ($$A55$$, $$https://www.kenhub.com/en/library/anatomy/the-deep-extensors-of-the-forearm$$, $$Kenhub: deep extensors of the forearm$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: the deep posterior group acts on the thumb and index finger, except the supinator, which acts on the proximal radioulnar joint. The group's members (supinator, abductor pollicis longus, extensor pollicis longus and brevis, extensor indicis) were listed in Kenhub's extensor indicis article (A37) rather than on this page's visible excerpt.$$),
  ($$A6$$, $$https://www.kenhub.com/en/library/anatomy/flexor-carpi-radialis-muscle$$, $$Kenhub: flexor carpi radialis muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: fusiform muscle in the superficial layer of the anterior forearm; key facts list wrist flexion and wrist abduction (radial deviation); medial epicondyle to the bases of metacarpals 2–3; median nerve.$$),
  ($$A7$$, $$https://www.imaios.cn/en/e-anatomy/anatomical-structures/flexor-carpi-radialis-14216924$$, $$IMAIOS e-Anatomy: flexor carpi radialis$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (imaios.cn mirror): primary functions wrist flexion and radial deviation, with a minor role in pronation; cites the StatPearls forearm muscles article as its reference.$$),
  ($$A8$$, $$https://www.ncbi.nlm.nih.gov/books/NBK526051/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Forearm Flexor Carpi Ulnaris Muscle$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results: superficial forearm flexor that flexes and adducts the hand; the most powerful wrist flexor; also a weak elbow flexor; humeral and ulnar heads; inserts on the pisiform, hook of hamate and fifth metacarpal; ulnar nerve. Updated 26 Jun 2023.$$),
  ($$A9$$, $$https://www.ncbi.nlm.nih.gov/books/NBK519516/$$, $$StatPearls: Anatomy, Shoulder and Upper Limb, Hand Palmaris Tendon$$, null, $$anatomy$$, $$2026-10-16$$, $$Checked via web-search results (PubMed 30137801): small muscle whose contribution as an accessory flexor at the elbow and wrist is likely minimal; appears to tension the palmar aponeurosis; commonly absent, and absence has not been shown to reduce grip strength or cause another functional deficit.$$),
  ($$M1$$, $$https://pmc.ncbi.nlm.nih.gov/articles/PMC4526813/$$, $$Kleiber, Kunz and Disselhorst-Klug, Muscular coordination of biceps brachii and brachioradialis in elbow flexion with respect to hand position (Frontiers in Physiology, 2015)$$, $$10.3389/fphys.2015.00215$$, $$emg$$, $$2026-10-16$$, $$16 healthy adults, slow single elbow flexions (20 degrees per second) with the hand pronated, neutral and supinated; surface EMG. The brachioradialis's contribution differed in pronation from supination and neutral, while biceps activity did not change with hand position; the authors relate this to the biceps's mechanical disadvantage in pronation. Acute, light task; other EMG studies disagree on the size of the position effect.$$),
  ($$M2$$, $$https://experts.mcmaster.ca/scholarly-works/1313379$$, $$Mogk and Keir, The effects of posture on forearm muscle loading during gripping (Ergonomics 46(9):956-975, 2003)$$, null, $$emg$$, $$2026-10-16$$, $$10 adults gripping a dynamometer at several efforts in three wrist and three forearm postures. Wrist-extensor activity accompanied gripping, was generally larger than flexor activity at low to moderate grip forces, and was always greater with the forearm pronated. Supports the wrist extensors steadying the wrist whenever the hand grips; a dynamometer is not a barbell, and EMG is not a growth measure.$$),
  ($$M3$$, $$https://doi.org/10.1016/j.physbeh.2020.113283$$, $$Jukic et al. (2021), lifting straps in the deadlift: movement velocity, grip strength and perceived grip security (Physiology & Behavior 229:113283)$$, $$10.1016/j.physbeh.2020.113283$$, $$biomechanics$$, $$2026-10-16$$, $$16 men deadlifting 4 sets of 4 with and without straps. With straps, grip strength fell less across the session and recovered faster, and grip felt more secure. Supports treating a strapped set's grip demand as different from an unstrapped one; it does not measure forearm muscle activity.$$),
  ($$M4$$, $$https://pubmed.ncbi.nlm.nih.gov/23101527/$$, $$Goetz et al., contribution of the flexor pollicis longus to pinch strength, measured before and after an EMG-guided lidocaine block (2012; PubMed 23101527)$$, null, $$biomechanics$$, $$2026-10-16$$, $$11 healthy volunteers; key, three-point and tip pinch strength fell after the flexor pollicis longus was temporarily blocked. Supports the long thumb flexor working in pinches; pinch-meter tasks, not plate pinches, and only the abstract was read.$$),
  ($$M5$$, $$https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12885837/$$, $$Kondi et al., An electromyographic study comparing muscle function during supination and pronation of the forearm (Cureus, 2026)$$, null, $$emg$$, $$2026-10-16$$, $$Pilot study, 4 adults, forearm held in neutral against a 1 kg load at increasing distances from the rotation axis (a lever). In supination the supinator was more active than the biceps at low torque and the biceps rose more steeply as torque increased; in pronation the pronator quadratus was more active at low torque and the pronator teres rose more steeply. Surface EMG for the pronators, fine wire for the supinator; isometric; very small sample.$$),
  ($$M6$$, $$https://pubmed.ncbi.nlm.nih.gov/12121684/$$, $$O'Sullivan and Gallwey, Upper-limb surface electro-myography at maximum supination and pronation torques: the effect of elbow and forearm angle (Journal of Electromyography and Kinesiology 12(4):275-285, 2002)$$, null, $$emg$$, $$2026-10-16$$, $$24 men, maximal pronation and supination efforts at four elbow angles and three forearm angles, surface EMG of six muscles including pronator teres, biceps and brachioradialis. Torque in both directions changed with elbow and forearm angle. Supports recording the elbow angle on the lever rows; maximal isometric efforts, not repetitions.$$),
  ($$M7$$, $$https://doi.org/10.1016/j.jelekin.2020.102428$$, $$Pratt, Hoffman, Grainger and Ditroilo, Forearm electromyographic activity during the deadlift exercise is affected by grip type and sex (Journal of Electromyography and Kinesiology, 2020)$$, $$10.1016/j.jelekin.2020.102428$$, $$emg$$, $$2026-10-16$$, $$Trained lifters deadlifting at 50, 70 and 90 per cent of their maximum with hook, mixed and double-overhand grips; forearm EMG changed with grip type and load. Cited only for that: secondary summaries disagree on which grip ranked highest, and the full text was not read.$$),
  ($$M8$$, $$https://anatomy.ttuhscep.edu/musculoskeletal_system/axilla_tables.html$$, $$Texas Tech University Health Sciences Center El Paso: axilla, posterior shoulder and arm muscle tables$$, null, $$anatomy$$, $$2026-10-16$$, $$The arm companion to S4, for the two upper-arm muscles the forearm atlas credits as external contributors: biceps brachii (elbow flexion, supination) and brachialis (elbow flexion only). Actions, not exercise loading.$$),
  ($$S1$$, $$https://doi.org/10.1007/s40279-025-02344-w$$, $$Pelland et al., The Resistance Training Dose Response: Meta-Regressions Exploring the Effects of Weekly Volume and Frequency on Muscle Hypertrophy and Strength Gains (Sports Medicine)$$, $$10.1007/s40279-025-02344-w$$, $$systematic_review$$, $$2026-10-16$$, $$Supports a positive volume–hypertrophy relationship with diminishing returns and fractional set counting as the best fit within the included studies. Does not set a forearm-muscle target.$$),
  ($$S2$$, $$https://pmc.ncbi.nlm.nih.gov/articles/PMC11740565/$$, $$Ikeda et al., Effects of forearm rotation on wrist flexor and extensor muscle activities (Journal of Orthopaedic Surgery and Research, 2025)$$, $$10.1186/s13018-024-05363-x$$, $$emg$$, $$2026-10-16$$, $$Acute, controlled isometric tasks. Not a longitudinal hypertrophy study. Checked via web-search results on 16 Oct 2026: surface EMG of ECRB, ECU, FCR and FCU in 40 healthy arms at a constant wrist torque of three quarters of the neutral-position maximum, in pronation, neutral and supination. ECRB was more active in pronation, ECU did not change, FCR was more active in supination, FCU was lower in pronation than neutral. ECRL was not recorded separately.$$),
  ($$S3$$, $$https://pmc.ncbi.nlm.nih.gov/articles/PMC1474175/$$, $$Butler, Kilbreath, Gorman and Gandevia, Selective recruitment of single motor units in human flexor digitorum superficialis muscle during flexion of individual fingers (Journal of Physiology, 2005)$$, $$10.1113/jphysiol.2005.089201$$, $$emg$$, $$2026-10-16$$, $$Finger-component specificity with coupling between fingers. Does not show complete isolation. Checked via web-search results on 16 Oct 2026 (abstract): isometric flexion of one finger at half of maximum activated fewer than half of the single units in FDS components of other fingers; recruitment at low force was mostly in adjacent fingers, with the ring and little fingers the most coupled.$$),
  ($$S4$$, $$https://anatomy.ttuhscep.edu/musculoskeletal_system/forearm_tables.html$$, $$Texas Tech University Health Sciences Center El Paso: forearm muscle reference (origins, insertions, actions)$$, null, $$anatomy$$, $$2026-10-16$$, $$Muscle identities and actions. This page did not appear in web-search results on 16 Oct 2026, so no claim cites it; the same site's alphabetical upper-limb reference (A38) did appear and is cited instead.$$),
  ($$S5$$, $$https://anatomy.ttuhscep.edu/musculoskeletal_system/forearm_ans.html$$, $$Texas Tech University Health Sciences Center El Paso: forearm dissection teaching material$$, null, $$anatomy$$, $$2026-10-16$$, $$Layers, orientation and identification. Not returned by web search on 16 Oct 2026; not cited by any claim.$$),
  ($$S6$$, $$https://pubmed.ncbi.nlm.nih.gov/31183837/$$, $$Rodrigues et al., Sonoanatomy of anterior forearm muscles (Journal of Ultrasound, 2019)$$, null, $$anatomy$$, $$2026-10-16$$, $$Superficial, intermediate and deep anterior structures. Checked via web-search results on 16 Oct 2026 (abstract and introduction only, PMC6704193): the anterior compartment's eight muscles split into superficial and deep groups. Layer-by-layer imaging findings were not seen.$$),
  ($$S7$$, $$https://anatomy.app/encyclopedia/flexor-carpi-radialis$$, $$Anatomy.app: flexor carpi radialis$$, null, $$anatomy$$, $$2026-10-16$$, $$Superficial location and wrist action; not a quantified appearance claim. Not returned by web search on 16 Oct 2026; FCR claims cite A6 and A7 instead.$$),
  ($$S8$$, $$https://www.ncbi.nlm.nih.gov/sites/books/NBK526046/$$, $$StatPearls: flexor digitorum profundus$$, null, $$anatomy$$, $$2026-10-16$$, $$Deep extrinsic finger flexor identity and joint actions. Web search on 16 Oct 2026 could not confirm that this Bookshelf id is the FDP article; the StatPearls FDP article was found as PubMed 30252302 (A14), which the FDP claims cite instead.$$)
on conflict (source_key) do update set url = excluded.url, title = excluded.title, doi = excluded.doi, evidence_type = excluded.evidence_type, retrieved_on = excluded.retrieved_on, notes = excluded.notes
  where (t.url, t.title, t.doi, t.evidence_type, t.retrieved_on, t.notes) is distinct from (excluded.url, excluded.title, excluded.doi, excluded.evidence_type, excluded.retrieved_on, excluded.notes);

-- Claims (key: <region>:<claim id>)
insert into specialization.claims as t (claim_key, node_id, kind, statement, basis, review_status, reviewed_on, review_note) values
  ($$forearm:anconeus.appearance$$, $$forearm.anconeus$$, $$appearance$$, $$Anconeus is a small triangular muscle at the back of the elbow, between the thumb-side bony knob of the upper-arm bone and the point of the elbow. It may add to the contour at the back of the elbow; it is not a forearm growth target.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:anconeus.function$$, $$forearm.anconeus$$, $$function$$, $$Anconeus helps straighten the elbow and helps steady the joint; the triceps does most of the straightening.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:anterior.appearance$$, $$forearm.anterior$$, $$appearance$$, $$Together the palm-side muscles make up most of the palm-side fullness of the forearm. Which muscle shapes which part of that outline cannot be read from the surface.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:anterior.function$$, $$forearm.anterior$$, $$function$$, $$The palm-side (anterior) compartment holds the muscles that bend the wrist and fingers and turn the palm down. They lie in a surface layer, a middle layer (flexor digitorum superficialis) and a deep layer.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:apl.appearance$$, $$forearm.apl$$, $$appearance$$, $$APL is a deep muscle of the back of the forearm whose tendon, with EPB's, forms the thumb-side edge of the hollow at the base of the thumb. A visible line there is mostly tendon; the belly has little separately visible contour.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:apl.function$$, $$forearm.apl$$, $$function$$, $$Abductor pollicis longus moves the thumb out from the hand at its base (the carpometacarpal joint) and helps straighten it there.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:biceps.appearance$$, $$upper_arm.biceps$$, $$appearance$$, $$Biceps shapes the front of the upper arm. It is an upper-arm muscle and does not add forearm size.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:biceps.function$$, $$upper_arm.biceps$$, $$function$$, $$Biceps brachii bends the elbow and turns the forearm palm-up; with the elbow bent it is the forearm's most powerful palm-up muscle.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:br.appearance$$, $$forearm.br$$, $$appearance$$, $$Brachioradialis is the most superficial muscle on the thumb side of the forearm and forms the fleshy bulge in its upper half, so it may contribute to the thumb-side contour just below the elbow. Visible shape also depends on neighbouring muscles, body fat and individual anatomy.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:br.function$$, $$forearm.br$$, $$function$$, $$Brachioradialis bends the elbow and is active whether the palm faces up, sideways or down. Anatomy references describe it as strongest with the forearm half-turned (thumb up). From a fully palm-up or palm-down start it also turns the forearm back toward thumb-up. It does not cross the wrist.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:br.selectivity.1$$, $$forearm.br$$, $$selectivity$$, $$Whether forearm position changes how hard the brachioradialis works when bending the elbow is unsettled. A surface-EMG study of 16 people found its share differed with the palm down compared with palm up or thumb up; a fine-wire EMG study of 10 people found no difference between the three positions. Neither study measured growth.$$, $$experimental$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:brachialis.appearance$$, $$upper_arm.brachialis$$, $$appearance$$, $$Brachialis lies under the biceps in the lower front of the upper arm and may show at its sides. It is not a forearm muscle.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:brachialis.function$$, $$upper_arm.brachialis$$, $$function$$, $$Brachialis bends the elbow in every forearm position and does not turn the forearm; it is described as a pure elbow flexor.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrb.appearance$$, $$forearm.ecrb$$, $$appearance$$, $$ECRB is shorter than ECRL and partly covered by it on the back and thumb side of the forearm, so it belongs to the extensor mass there with only a partly visible outline of its own.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrb.function$$, $$forearm.ecrb$$, $$function$$, $$Extensor carpi radialis brevis bends the wrist back and is described as the main wrist extensor; with ECRL it tilts the hand toward the thumb side.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrb.selectivity.1$$, $$forearm.ecrb$$, $$selectivity$$, $$No ordinary exercise is known to train ECRB apart from ECRL. They share both wrist actions and lie side by side, and separating their EMG takes fine wires placed by measurement; surface electrodes record them together. The atlas does not split their work.$$, $$experimental$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrb.selectivity.2$$, $$forearm.ecrb$$, $$selectivity$$, $$In a controlled study of 40 arms holding the same wrist-extension force, ECRB was more active with the palm turned down. Forearm rotation therefore belongs in how an exercise is described; the study does not show which position grows the muscle more, and it did not record ECRL.$$, $$experimental$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrl.appearance$$, $$forearm.ecrl$$, $$appearance$$, $$ECRL starts just above the elbow on the thumb side and runs beside the brachioradialis in the surface layer of the back of the forearm, so it may contribute to the contour on the back and thumb side near the elbow.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrl.function$$, $$forearm.ecrl$$, $$function$$, $$Extensor carpi radialis longus bends the wrist back (extension) and tilts the hand toward the thumb side (radial deviation).$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecrl.selectivity.1$$, $$forearm.ecrl$$, $$selectivity$$, $$No ordinary exercise is known to train ECRL apart from ECRB. Both bend the wrist back and toward the thumb side, they lie side by side, and EMG texts long held that their activity could not be told apart even with needle electrodes: recording them separately takes fine wires placed by measurement, and surface electrodes record them together. The atlas does not split their work.$$, $$experimental$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecu.appearance$$, $$forearm.ecu$$, $$appearance$$, $$ECU runs in the surface layer along the pinky-side edge of the back of the forearm, from the elbow to the wrist, so it may contribute to the contour there.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:ecu.function$$, $$forearm.ecu$$, $$function$$, $$Extensor carpi ulnaris bends the wrist back (with ECRL and ECRB) and tilts the hand toward the pinky side (with FCU).$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ecu.selectivity.1$$, $$forearm.ecu$$, $$selectivity$$, $$In the controlled wrist-extension study, ECU activity did not change between palm up, thumb up and palm down. That is one acute finding, not evidence that forearm position never matters for ECU.$$, $$experimental$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ed.appearance$$, $$forearm.ed$$, $$appearance$$, $$Extensor digitorum lies in the middle of the back of the forearm in the surface layer and splits into four tendons about a third of the way down, so it may contribute to the central mass on the back of the forearm. Its tendons on the back of the hand are not muscle bulk.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:ed.function$$, $$forearm.ed$$, $$function$$, $$Extensor digitorum straightens the four fingers, mainly at the knuckles (MCP) and also at their other joints, and helps bend the wrist back.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:edm.appearance$$, $$forearm.edm$$, $$appearance$$, $$EDM is a thin muscle on the pinky side of extensor digitorum, joined to it near the elbow and separate from about mid-forearm; some anatomists treat it as part of extensor digitorum. It is not a major independent driver of forearm width.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:edm.function$$, $$forearm.edm$$, $$function$$, $$Extensor digiti minimi straightens the little finger, mainly at the knuckle, and can do so independently of the other fingers.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:ei.appearance$$, $$forearm.ei$$, $$appearance$$, $$Extensor indicis is a narrow muscle in the deep layer of the back of the forearm near the wrist, so it has little or no separately visible contour.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:ei.function$$, $$forearm.ei$$, $$function$$, $$Extensor indicis straightens the index finger at its knuckle and other joints, which lets the index finger straighten on its own.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:epb.appearance$$, $$forearm.epb$$, $$appearance$$, $$EPB is small and deep. Its tendon, with APL's, forms the thumb-side edge of the hollow at the base of the thumb, so a visible tendon there says little about the size of the muscle belly.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:epb.function$$, $$forearm.epb$$, $$function$$, $$Extensor pollicis brevis straightens the thumb at its knuckle (MCP) and helps straighten it at its base.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:epb.variation.1$$, $$forearm.epb$$, $$variation$$, $$Where the EPB tendon attaches varies a good deal between people; in one cadaver study only a quarter of tendons attached in the textbook way, at the base of the thumb's first bone.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:epl.appearance$$, $$forearm.epl$$, $$appearance$$, $$EPL lies in the deep layer of the back of the forearm. Its long tendon passes around a bony bump on the back of the radius (Lister's tubercle) and forms the pinky-side edge of the hollow at the base of the thumb; the belly has little or no separately visible contour.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:epl.function$$, $$forearm.epl$$, $$function$$, $$Extensor pollicis longus straightens the tip (IP joint) of the thumb and also straightens the thumb at its knuckle (MCP).$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fcr.appearance$$, $$forearm.fcr$$, $$appearance$$, $$FCR lies in the surface layer of the palm side, slanting from the pinky side of the elbow toward the thumb side of the wrist, so it may contribute to the palm-side contour toward the thumb side. It is not the whole thumb-side width; the brachioradialis forms that edge.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:fcr.function$$, $$forearm.fcr$$, $$function$$, $$Flexor carpi radialis bends the wrist toward the palm and tilts the hand toward the thumb side (radial deviation).$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fcr.selectivity.1$$, $$forearm.fcr$$, $$selectivity$$, $$In a controlled study of 40 arms holding the same wrist-flexion force, FCR was more active with the palm turned up than with the thumb up or the palm down. Forearm rotation therefore belongs in how an exercise is described; the study does not show which position grows the muscle more.$$, $$experimental$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fcu.appearance$$, $$forearm.fcu$$, $$appearance$$, $$FCU runs in the surface layer along the pinky-side edge of the palm side, from the elbow to the wrist, so it may contribute to the palm-side ulnar contour. Visible shape also depends on neighbouring muscles and individual anatomy.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:fcu.function$$, $$forearm.fcu$$, $$function$$, $$Flexor carpi ulnaris bends the wrist toward the palm and tilts the hand toward the pinky side (ulnar deviation). Anatomy references describe it as the most powerful wrist flexor.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fcu.selectivity.1$$, $$forearm.fcu$$, $$selectivity$$, $$In the same controlled wrist-flexion study, FCU was less active with the palm turned down than with the thumb up. This is evidence that forearm rotation changes wrist-flexor activity, not that one position grows FCU more.$$, $$experimental$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fdp.appearance$$, $$forearm.fdp$$, $$appearance$$, $$FDP lies in the deep layer of the palm side, against the ulna under the other finger flexors, and is hard to feel through the skin. It may add to overall palm-side thickness but has little or no separately visible surface contour, so it cannot be drawn as an isolated surface stripe.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:fdp.function$$, $$forearm.fdp$$, $$function$$, $$Flexor digitorum profundus is the only muscle that bends the four fingers at their end (DIP) joints. It also helps bend the middle joints, the knuckles and the wrist. The force it makes at the fingertips depends on wrist position and falls when the wrist is fully bent.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fdp.selectivity.1$$, $$forearm.fdp$$, $$selectivity$$, $$Ordinary gym grip and finger-flexion exercises load FDP together with FDS. In a video-EMG study of fist making, FDP did most of the work in a light fist and FDS joined in every tight fist. No ordinary exercise has been shown to train FDP apart from FDS, so the atlas shows the work as shared and invents no split.$$, $$experimental$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fds.appearance$$, $$forearm.fds$$, $$appearance$$, $$FDS forms the middle layer of the palm side, covered by the surface wrist flexors and lying over the deep finger flexor, so it may add to the general fullness of the palm side but has no separately visible outline.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:fds.function$$, $$forearm.fds$$, $$function$$, $$Flexor digitorum superficialis is the main muscle bending the four fingers at their middle (PIP) joints. It also helps bend the knuckles (MCP) and the wrist. It has a separate part, with its own tendon, for each finger.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fds.selectivity.1$$, $$forearm.fds$$, $$selectivity$$, $$The finger parts of FDS can be recruited selectively to some degree, with coupling between fingers. When one finger flexed at half its maximum force, fewer than half of the motor units serving the other fingers' parts became active, and units serving a neighbouring finger were recruited most readily. This supports describing finger actions; it does not show that one finger's part can be trained in isolation.$$, $$experimental$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fds.selectivity.2$$, $$forearm.fds$$, $$selectivity$$, $$Ordinary gym grip and finger-flexion exercises load FDS together with the deep finger flexor (FDP). In a video-EMG study of fist making, FDP did most of the work in a light fist and FDS joined in every tight fist, in an order that differed between people. No ordinary exercise has been shown to split the work between them, so the atlas shows it as shared and invents no split.$$, $$experimental$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:fpl.appearance$$, $$forearm.fpl$$, $$appearance$$, $$FPL lies in the deep layer on the thumb side of the palm side, close to the radius and under the surface and middle flexors, so it has little or no separately visible contour.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:fpl.function$$, $$forearm.fpl$$, $$function$$, $$Flexor pollicis longus is the only muscle that bends the tip (IP joint) of the thumb, and it also helps bend the thumb at its knuckle.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:pl.appearance$$, $$forearm.pl$$, $$appearance$$, $$Palmaris longus has a small belly near the elbow and a long tendon, and it is missing in some people, so it is not a major driver of forearm width. Any contribution would be to the middle of the palm-side contour near the elbow.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:pl.function$$, $$forearm.pl$$, $$function$$, $$Palmaris longus tenses the sheet of connective tissue in the palm (palmar aponeurosis). It crosses the wrist but is small, so its help in bending the wrist is likely minimal.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:pl.variation.1$$, $$forearm.pl$$, $$variation$$, $$Palmaris longus is absent on one or both sides in a minority of people, and how often depends strongly on the population. A review pooling 26 clinical studies found the lowest rates in East and South-East African groups and the highest in Arab Middle Eastern groups, so no single figure applies to everyone. Its absence has not been shown to reduce grip strength.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:posterior.appearance$$, $$forearm.posterior$$, $$appearance$$, $$Together the back-of-forearm muscles make up the back of the forearm and, through the brachioradialis and the thumb-side wrist extensors, the thumb-side outline near the elbow.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:posterior.function$$, $$forearm.posterior$$, $$function$$, $$The back (posterior) compartment holds the muscles that straighten the wrist, fingers and thumb and turn the palm up, plus the brachioradialis, which bends the elbow. They lie in a surface layer and a deep layer.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:pq.appearance$$, $$forearm.pq$$, $$appearance$$, $$Pronator quadratus is the most distal muscle of the deepest palm-side layer, a flat square muscle on the bones just above the wrist under the flexor tendons, so it has little or no direct surface definition.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:pq.function$$, $$forearm.pq$$, $$function$$, $$Pronator quadratus turns the forearm palm-down (pronation). It is also a dynamic stabiliser of the joint between the two forearm bones at the wrist (the distal radioulnar joint), pressing them together.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:pt.appearance$$, $$forearm.pt$$, $$appearance$$, $$Pronator teres lies in the surface layer just below the elbow, slanting from the pinky side of the elbow to the middle of the radius on the thumb side, and forms the pinky-side edge of the hollow in front of the elbow. It may contribute to the slanted palm-side contour there.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:pt.function$$, $$forearm.pt$$, $$function$$, $$Pronator teres turns the forearm palm-down (pronation) and gives a small amount of help bending the elbow.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$),
  ($$forearm:supinator.appearance$$, $$forearm.supinator$$, $$appearance$$, $$Supinator lies in the deep layer just below the elbow, wrapped around the top of the radius under the surface extensors, so it is not directly visible in an ordinary surface view.$$, $$anatomical_inference$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026, as an anatomical inference from the muscle's cited location and depth; not a measured prediction. Automated review, not a clinician or anatomist.$$),
  ($$forearm:supinator.function$$, $$forearm.supinator$$, $$function$$, $$Supinator turns the forearm palm-up (supination) at the joint between the forearm bones near the elbow. With the elbow bent, the biceps is the stronger palm-up muscle; with the elbow straight, the biceps contributes little.$$, $$established_anatomy$$, $$reviewed$$, $$2026-10-16$$, $$Checked against the cited sources through web search on 16 Oct 2026; automated review, not a clinician or anatomist.$$)
