  ($$forearm.pt$$, $$elbow.flexion$$, $$assist$$, $$forearm:pt.function$$),
  ($$forearm.pt$$, $$forearm.pronation$$, $$prime$$, $$forearm:pt.function$$),
  ($$forearm.supinator$$, $$forearm.supination$$, $$prime$$, $$forearm:supinator.function$$),
  ($$upper_arm.biceps$$, $$elbow.flexion$$, $$prime$$, $$forearm:biceps.function$$),
  ($$upper_arm.biceps$$, $$forearm.supination$$, $$prime$$, $$forearm:biceps.function$$),
  ($$upper_arm.brachialis$$, $$elbow.flexion$$, $$prime$$, $$forearm:brachialis.function$$)
) as x (node_id, action_id, role, claim_key)
left join specialization.claims c on c.claim_key = x.claim_key
on conflict (node_id, action_id) do update set role = excluded.role, claim_id = excluded.claim_id
  where (t.role, t.claim_id) is distinct from (excluded.role, excluded.claim_id);

