on conflict (variant_key) do update set catalog_id = excluded.catalog_id, organization = excluded.organization, forearm_orientation = excluded.forearm_orientation, wrist_position = excluded.wrist_position, grip_type = excluded.grip_type, straps = excluded.straps, laterality = excluded.laterality, phase = excluded.phase, measure = excluded.measure, deliberate_hold = excluded.deliberate_hold, elbow_angle_deg = excluded.elbow_angle_deg, notes = excluded.notes
  where (t.catalog_id, t.organization, t.forearm_orientation, t.wrist_position, t.grip_type, t.straps, t.laterality, t.phase, t.measure, t.deliberate_hold, t.elbow_angle_deg, t.notes) is distinct from (excluded.catalog_id, excluded.organization, excluded.forearm_orientation, excluded.wrist_position, excluded.grip_type, excluded.straps, excluded.laterality, excluded.phase, excluded.measure, excluded.deliberate_hold, excluded.elbow_angle_deg, excluded.notes);

-- Accounting rule versions (immutable once published)
insert into specialization.rule_versions as t (id, specification, published_at, notes) values
  ($$specialization_exposure_v1$$, $${"bout":"One logged work set, or one planned set. Each bout has an id; a standard set is one segment.","dropSet":"A drop set is one bout. Its stages are segments, each with its own load and reps. It is never counted as several sets.","excludedFromCompleted":["Sets not logged as completed (typed but not logged, or skipped).","Sets marked as warm-ups.","Workouts not finished (the live workout's sets count once it is finished).","Removed workouts and sets (they no longer exist on the device)."],"categories":{"direct_dynamic":"The muscle performs the movement through its range in this exercise (a reviewed direct, dynamic mapping).","contributing_dynamic":"The muscle helps move the load but is not the main target (a reviewed contributing, dynamic mapping).","deliberate_isometric":"The muscle holds against load in an exercise whose purpose is the hold (hangs, carries, pinches).","incidental_isometric":"The muscle holds or steadies while something else is trained (gripping a bar during a row).","mixed":"One set loads the muscle in two different ways; it counts once here, with the parts listed.","unknown":"The mapping exists but its relationship or muscle action is not known."},"perNodeBout":"A muscle counts a bout once. Two categories from one bout make it `mixed`, with the parts listed.","sides":"A two-handed bout counts once for each arm (3 sets are 3 per arm, not 6). A one-arm bout counts for that arm only. A bout whose side is unknown is reported separately and never added to either arm.","straps":"Grip credit that needs a bare hand is not given to a set logged with straps. Unknown straps keep the credit and say so.","holds":"Hold seconds are summed per segment and reported as seconds. They are never converted into sets.","unmapped":"Work tagged with the region in the exercise catalog but with no reviewed atlas mapping counts only at region level, never as work for a specific muscle. Draft mappings are shown as pending review and not counted. Unknown is never shown as zero.","regionTotal":"The region total counts distinct bouts that touched any of its muscles on that arm. It is not the sum of the muscle rows.","notConverted":["Load × reps is external volume-load, not muscle force.","Effort that was not recorded stays unknown; it never defaults to failure.","Incidental grip is never counted as dynamic work.","No number here predicts growth, recovery or injury."]}$$::jsonb, $$2026-10-16 00:00:00+00$$, $$First published accounting model for specialization exposure. Raw categories only; no fractional set model.$$)
on conflict (id) do update set specification = excluded.specification, published_at = excluded.published_at, notes = excluded.notes
  where (t.specification, t.published_at, t.notes) is distinct from (excluded.specification, excluded.published_at, excluded.notes);

-- Mapping versions, inserted as drafts (published below, once their rows are in)
insert into specialization.mapping_versions as t (version_key, region_id, state, published_at, method_notes) values
  ($$forearm_mappings_v1$$, $$forearm$$, $$draft$$, null, $$Each catalog exercise the forearm atlas maps has one default variant (cat-<id>) with its execution spelled out: organization, forearm orientation, wrist position, grip, straps, laterality, measure, deliberate hold, and an elbow angle only where the exercise defines one. Each mapping names one muscle, one joint action, a relationship (direct, contributing, stabilizer, incidental) and a muscle mode (dynamic or isometric) separately, so one set can be dynamic elbow flexion and isometric wrist stabilization at once. Mappings are by catalog id; no name matching. A mapping is reviewed when the muscle's action is sourced (anatomy tables S4, S7, S8, the arm reference M8) and the relationship is explained in its rationale; EMG sources (S2, S3, M1, M2, M5-M7) are cited only for what they measured. Everything else stays draft and is shown as pending review, never counted. FDS and FDP are always credited together as shared: nothing in an ordinary grip separates them. Grip during rows, pulldowns, pull-ups, deadlifts, shrugs and hangs is incidental and is not earned by a set logged with straps. No percentage splits between muscles, no mapping credits every forearm muscle, the hand's own muscles are not credited to the forearm, and a broad 'forearms' tag on an unmapped exercise stays region-level.$$)
on conflict (version_key) do update set region_id = excluded.region_id, method_notes = excluded.method_notes
  where (t.region_id, t.method_notes) is distinct from (excluded.region_id, excluded.method_notes);

-- Variant mappings (draft rows are kept: shown as pending review, never counted, never readable by users)
insert into specialization.variant_mappings as t (version_id, mapping_key, variant_key, node_id, action_id, relationship, muscle_mode, evidence_basis, allocation, requires_no_straps, rationale, review_status)
select v.id, x.mapping_key, x.variant_key, x.node_id, x.action_id, x.relationship, x.muscle_mode, x.evidence_basis, x.allocation, x.requires_no_straps, x.rationale, x.review_status
from (values
  ($$forearm_mappings_v1$$, $$cat-121:forearm.br$$, $$cat-121$$, $$forearm.br$$, $$elbow.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The brachioradialis is an elbow flexor and moves through range in every curl, so it gets dynamic credit; with the palms up it is a helper rather than the curl's target, so it is contributing, not direct.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-121:forearm.fdp$$, $$cat-121$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar, dumbbell or handle while the elbow flexors work: a real but incidental grip, not finger-flexor training. FDS and FDP share it; nothing here splits it between them.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-121:forearm.fds$$, $$cat-121$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar, dumbbell or handle while the elbow flexors work: a real but incidental grip, not finger-flexor training. FDS and FDP share it; nothing here splits it between them.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-121:upper_arm.biceps$$, $$cat-121$$, $$upper_arm.biceps$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A palms-up curl is built on elbow flexion with the forearm supinated, the position in which the biceps flexes the elbow best. It is credited as an upper-arm muscle beside the forearm, not as forearm work.$$, $$reviewed$$),
