  ($$forearm_mappings_v1$$, $$cat-138:forearm.br$$, $$cat-138$$, $$forearm.br$$, $$elbow.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The brachioradialis is an elbow flexor and moves through range in every curl, so it gets dynamic credit; with the palms up it is a helper rather than the curl's target, so it is contributing, not direct.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-138:forearm.fdp$$, $$cat-138$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The hands hold the bar against body weight while the elbows bend: an incidental grip, shared between FDS and FDP. Straps would take it off the fingers, so a strapped set earns no grip credit.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-138:forearm.fds$$, $$cat-138$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The hands hold the bar against body weight while the elbows bend: an incidental grip, shared between FDS and FDP. Straps would take it off the fingers, so a strapped set earns no grip credit.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-138:upper_arm.biceps$$, $$cat-138$$, $$upper_arm.biceps$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A palms-up curl is built on elbow flexion with the forearm supinated, the position in which the biceps flexes the elbow best. It is credited as an upper-arm muscle beside the forearm, not as forearm work.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-138:upper_arm.brachialis$$, $$cat-138$$, $$upper_arm.brachialis$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The brachialis flexes the elbow whatever the forearm's rotation, so every curl works it directly. Credited as an upper-arm muscle beside the forearm.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-139:forearm.fcr$$, $$cat-139$$, $$forearm.fcr$$, $$wrist.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A wrist curl is built on wrist flexion, the flexor carpi radialis's main action; the wrist moves through range against the load.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-139:forearm.fcu$$, $$cat-139$$, $$forearm.fcu$$, $$wrist.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A wrist curl is built on wrist flexion, the flexor carpi ulnaris's main action; the wrist moves through range against the load.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-139:forearm.fdp$$, $$cat-139$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or dumbbell while the wrist moves: incidental grip, shared between FDS and FDP. If the bar is let roll to the fingertips the fingers also move, but that is not part of the definition and is not credited.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-139:forearm.fds$$, $$cat-139$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or dumbbell while the wrist moves: incidental grip, shared between FDS and FDP. If the bar is let roll to the fingertips the fingers also move, but that is not part of the definition and is not credited.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-139:forearm.pl$$, $$cat-139$$, $$forearm.pl$$, $$wrist.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The palmaris longus is a weak wrist flexor, so it helps rather than leads; it is absent in some people, and its credit means nothing for them.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-140:forearm.ecrb$$, $$cat-140$$, $$forearm.ecrb$$, $$wrist.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A reverse wrist curl is built on wrist extension, one of the extensor carpi radialis brevis's main actions; the wrist moves through range against the load. Nothing in this exercise is known to favour one radial extensor over the other, so the longus and brevis are credited alike.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-140:forearm.ecrl$$, $$cat-140$$, $$forearm.ecrl$$, $$wrist.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A reverse wrist curl is built on wrist extension, one of the extensor carpi radialis longus's main actions; the wrist moves through range against the load. Nothing in this exercise is known to favour one radial extensor over the other, so the longus and brevis are credited alike.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-140:forearm.ecu$$, $$cat-140$$, $$forearm.ecu$$, $$wrist.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A reverse wrist curl is built on wrist extension, one of the extensor carpi ulnaris's main actions; the wrist moves through range against the load.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-140:forearm.ed$$, $$cat-140$$, $$forearm.ed$$, $$wrist.extension$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The extensor digitorum assists wrist extension, but its main job is straightening the fingers, which stay closed on the bar; it is contributing, not direct. This is wrist extension, not finger extension.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-140:forearm.fdp$$, $$cat-140$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or handle while the wrist moves: incidental grip, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-140:forearm.fds$$, $$cat-140$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or handle while the wrist moves: incidental grip, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-141:forearm.ecrb$$, $$cat-141$$, $$forearm.ecrb$$, $$wrist.extension$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Winding the roller moves each wrist through flexion and extension against the hanging weight, but which way it is wound (and so which group lifts and which lowers) is not recorded. Both groups are credited as contributing and shared, rather than as direct work for either.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-141:forearm.ecrl$$, $$cat-141$$, $$forearm.ecrl$$, $$wrist.extension$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Winding the roller moves each wrist through flexion and extension against the hanging weight, but which way it is wound (and so which group lifts and which lowers) is not recorded. Both groups are credited as contributing and shared, rather than as direct work for either.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-141:forearm.ecu$$, $$cat-141$$, $$forearm.ecu$$, $$wrist.extension$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Winding the roller moves each wrist through flexion and extension against the hanging weight, but which way it is wound (and so which group lifts and which lowers) is not recorded. Both groups are credited as contributing and shared, rather than as direct work for either.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-141:forearm.fcr$$, $$cat-141$$, $$forearm.fcr$$, $$wrist.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Winding the roller moves each wrist through flexion and extension against the hanging weight, but which way it is wound (and so which group lifts and which lowers) is not recorded. Both groups are credited as contributing and shared, rather than as direct work for either.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-141:forearm.fcu$$, $$cat-141$$, $$forearm.fcu$$, $$wrist.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Winding the roller moves each wrist through flexion and extension against the hanging weight, but which way it is wound (and so which group lifts and which lowers) is not recorded. Both groups are credited as contributing and shared, rather than as direct work for either.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-141:forearm.fdp$$, $$cat-141$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the roller's handle throughout: incidental grip, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-141:forearm.fds$$, $$cat-141$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the roller's handle throughout: incidental grip, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-142:forearm.fdp$$, $$cat-142$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, false, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps do not apply to a pinch. The hand's own muscles also work in a pinch and are not credited to the forearm.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-142:forearm.fds$$, $$cat-142$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, false, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps do not apply to a pinch. The hand's own muscles also work in a pinch and are not credited to the forearm.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-142:forearm.fpl$$, $$cat-142$$, $$forearm.fpl$$, $$thumb.ip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$individual$$, false, $$The thumb presses the plates against the fingers for the whole hold, and the long thumb flexor adds measurably to pinch strength (M4), so it is a direct isometric target in a pinch.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-143:forearm.fdp$$, $$cat-143$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps would take the hold off the fingers, so a strapped hang earns no grip credit.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-143:forearm.fds$$, $$cat-143$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps would take the hold off the fingers, so a strapped hang earns no grip credit.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-144:forearm.fdp$$, $$cat-144$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Gripping a towel closes the fist further than a bar. Straps would take the hold off the fingers, so a strapped hang earns no grip credit.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-144:forearm.fds$$, $$cat-144$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Gripping a towel closes the fist further than a bar. Straps would take the hold off the fingers, so a strapped hang earns no grip credit.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-144:forearm.fpl$$, $$cat-144$$, $$forearm.fpl$$, $$thumb.ip_flexion$$, $$contributing$$, $$isometric$$, $$inference$$, $$individual$$, false, $$The thumb wraps the towel and presses on it, so the long thumb flexor likely helps hold; how much is not established, so this stays pending review.$$, $$draft$$),
  ($$forearm_mappings_v1$$, $$cat-145:forearm.ecrb$$, $$cat-145$$, $$forearm.ecrb$$, $$wrist.extension$$, $$stabilizer$$, $$isometric$$, $$emg$$, $$individual$$, false, $$A heavy handle held at the side needs the wrist held straight while the fingers grip, and the wrist extensors work alongside a grip (M2): isometric stabilization, never dynamic credit (brief §4, farmer carry: wrist stabilization).$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-145:forearm.ecrl$$, $$cat-145$$, $$forearm.ecrl$$, $$wrist.extension$$, $$stabilizer$$, $$isometric$$, $$emg$$, $$individual$$, false, $$A heavy handle held at the side needs the wrist held straight while the fingers grip, and the wrist extensors work alongside a grip (M2): isometric stabilization, never dynamic credit (brief §4, farmer carry: wrist stabilization).$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-145:forearm.ecu$$, $$cat-145$$, $$forearm.ecu$$, $$wrist.extension$$, $$stabilizer$$, $$isometric$$, $$emg$$, $$individual$$, false, $$A heavy handle held at the side needs the wrist held straight while the fingers grip, and the wrist extensors work alongside a grip (M2): isometric stabilization, never dynamic credit (brief §4, farmer carry: wrist stabilization).$$, $$reviewed$$),
