  ($$forearm_mappings_v1$$, $$cat-264:forearm.fds$$, $$cat-264$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The fingers hold the bar, dumbbells or handle while the hips, legs or upper back move the load: a real but incidental grip, shared between FDS and FDP. Straps take load off the fingers (M3), so a set logged with straps earns no grip credit; one with straps not recorded keeps it and says so.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-299:forearm.ecrb$$, $$cat-299$$, $$forearm.ecrb$$, $$wrist.extension$$, $$stabilizer$$, $$isometric$$, $$emg$$, $$individual$$, false, $$A heavy handle held at the side needs the wrist held straight while the fingers grip, and the wrist extensors work alongside a grip (M2): isometric stabilization, never dynamic credit (brief §4, farmer carry: wrist stabilization).$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-299:forearm.ecrl$$, $$cat-299$$, $$forearm.ecrl$$, $$wrist.extension$$, $$stabilizer$$, $$isometric$$, $$emg$$, $$individual$$, false, $$A heavy handle held at the side needs the wrist held straight while the fingers grip, and the wrist extensors work alongside a grip (M2): isometric stabilization, never dynamic credit (brief §4, farmer carry: wrist stabilization).$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-299:forearm.ecu$$, $$cat-299$$, $$forearm.ecu$$, $$wrist.extension$$, $$stabilizer$$, $$isometric$$, $$emg$$, $$individual$$, false, $$A heavy handle held at the side needs the wrist held straight while the fingers grip, and the wrist extensors work alongside a grip (M2): isometric stabilization, never dynamic credit (brief §4, farmer carry: wrist stabilization).$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-299:forearm.fdp$$, $$cat-299$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps would take the load off the fingers, so a strapped set earns no grip credit.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-299:forearm.fds$$, $$cat-299$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps would take the load off the fingers, so a strapped set earns no grip credit.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-299:forearm.fpl$$, $$cat-299$$, $$forearm.fpl$$, $$thumb.ip_flexion$$, $$contributing$$, $$isometric$$, $$inference$$, $$individual$$, false, $$The thumb closes over the handle, so the long thumb flexor likely helps hold it; how much it is loaded in a handle grip, as opposed to a pinch, is not established, so this stays pending review.$$, $$draft$$),
  ($$forearm_mappings_v1$$, $$cat-300:forearm.br$$, $$cat-300$$, $$forearm.br$$, $$elbow.flexion$$, $$contributing$$, $$isometric$$, $$anatomy$$, $$individual$$, false, $$The bar sits in the crook of the elbows, and the elbow flexors hold the elbows bent against it for the whole carry. The hands do not grip the bar, so no finger flexor is credited.$$, $$reviewed$$),
