  ($$forearm_mappings_v1$$, $$cat-332:forearm.fds$$, $$cat-332$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The fingers hold the bar or handle while the back and arms move the load: a real but incidental grip, shared between FDS and FDP. Straps take load off the fingers (M3), so a set logged with straps earns no grip credit; one with straps not recorded keeps it and says so.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-336:forearm.br$$, $$cat-336$$, $$forearm.br$$, $$elbow.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The brachioradialis is an elbow flexor and moves through range in every curl, so it gets dynamic credit; with the palms up it is a helper rather than the curl's target, so it is contributing, not direct.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-336:forearm.fdp$$, $$cat-336$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar, dumbbell or handle while the elbow flexors work: a real but incidental grip, not finger-flexor training. FDS and FDP share it; nothing here splits it between them.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-336:forearm.fds$$, $$cat-336$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar, dumbbell or handle while the elbow flexors work: a real but incidental grip, not finger-flexor training. FDS and FDP share it; nothing here splits it between them.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-336:upper_arm.biceps$$, $$cat-336$$, $$upper_arm.biceps$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A palms-up curl is built on elbow flexion with the forearm supinated, the position in which the biceps flexes the elbow best. It is credited as an upper-arm muscle beside the forearm, not as forearm work.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-336:upper_arm.brachialis$$, $$cat-336$$, $$upper_arm.brachialis$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The brachialis flexes the elbow whatever the forearm's rotation, so every curl works it directly. Credited as an upper-arm muscle beside the forearm.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-337:forearm.br$$, $$cat-337$$, $$forearm.br$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$inference$$, $$individual$$, false, $$Hammer-style curls keep the forearm in neutral, where the brachioradialis lies well placed to flex the elbow, and they are the usual choice to train it, so it is a direct target here. EMG studies disagree on how much its activity changes with forearm position (M1 found the change in pronation), so 'direct' is a judgement about the exercise's purpose, not a measured larger share.$$, $$reviewed$$),
