  ($$forearm_mappings_v1$$, $$cat-341:forearm.fds$$, $$cat-341$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar, dumbbell or handle while the elbow flexors work: a real but incidental grip, not finger-flexor training. FDS and FDP share it; nothing here splits it between them.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-341:upper_arm.biceps$$, $$cat-341$$, $$upper_arm.biceps$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A palms-up curl is built on elbow flexion with the forearm supinated, the position in which the biceps flexes the elbow best. It is credited as an upper-arm muscle beside the forearm, not as forearm work.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-341:upper_arm.brachialis$$, $$cat-341$$, $$upper_arm.brachialis$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The brachialis flexes the elbow whatever the forearm's rotation, so every curl works it directly. Credited as an upper-arm muscle beside the forearm.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-342:forearm.br$$, $$cat-342$$, $$forearm.br$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$inference$$, $$individual$$, false, $$Hammer-style curls keep the forearm in neutral, where the brachioradialis lies well placed to flex the elbow, and they are the usual choice to train it, so it is a direct target here. EMG studies disagree on how much its activity changes with forearm position (M1 found the change in pronation), so 'direct' is a judgement about the exercise's purpose, not a measured larger share.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-342:forearm.fdp$$, $$cat-342$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar, dumbbell or handle while the elbow flexors work: a real but incidental grip, not finger-flexor training. FDS and FDP share it; nothing here splits it between them.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-342:forearm.fds$$, $$cat-342$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar, dumbbell or handle while the elbow flexors work: a real but incidental grip, not finger-flexor training. FDS and FDP share it; nothing here splits it between them.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-342:upper_arm.biceps$$, $$cat-342$$, $$upper_arm.biceps$$, $$elbow.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The biceps still flexes the elbow with the palms facing in, but this curl is chosen for the brachioradialis and brachialis, so the biceps is credited as contributing.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-342:upper_arm.brachialis$$, $$cat-342$$, $$upper_arm.brachialis$$, $$elbow.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The brachialis flexes the elbow whatever the forearm's rotation, so every curl works it directly. Credited as an upper-arm muscle beside the forearm.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-350:forearm.ecrb$$, $$cat-350$$, $$forearm.ecrb$$, $$wrist.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A reverse wrist curl is built on wrist extension, one of the extensor carpi radialis brevis's main actions; the wrist moves through range against the load. Nothing in this exercise is known to favour one radial extensor over the other, so the longus and brevis are credited alike.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-350:forearm.ecrl$$, $$cat-350$$, $$forearm.ecrl$$, $$wrist.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A reverse wrist curl is built on wrist extension, one of the extensor carpi radialis longus's main actions; the wrist moves through range against the load. Nothing in this exercise is known to favour one radial extensor over the other, so the longus and brevis are credited alike.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-350:forearm.ecu$$, $$cat-350$$, $$forearm.ecu$$, $$wrist.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A reverse wrist curl is built on wrist extension, one of the extensor carpi ulnaris's main actions; the wrist moves through range against the load.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-350:forearm.ed$$, $$cat-350$$, $$forearm.ed$$, $$wrist.extension$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The extensor digitorum assists wrist extension, but its main job is straightening the fingers, which stay closed on the bar; it is contributing, not direct. This is wrist extension, not finger extension.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-350:forearm.fdp$$, $$cat-350$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or handle while the wrist moves: incidental grip, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-350:forearm.fds$$, $$cat-350$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or handle while the wrist moves: incidental grip, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-379:forearm.br$$, $$cat-379$$, $$forearm.br$$, $$elbow.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The elbows bend under load in a row, pulldown or pull-up, and the brachioradialis is an elbow flexor, so it helps move the load through range. Its share changes with hand position (M1), and the back muscles are the target, so it is contributing, never direct.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-379:forearm.fdp$$, $$cat-379$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The fingers hold the bar or handle while the back and arms move the load: a real but incidental grip, shared between FDS and FDP. Straps take load off the fingers (M3), so a set logged with straps earns no grip credit; one with straps not recorded keeps it and says so.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-379:forearm.fds$$, $$cat-379$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The fingers hold the bar or handle while the back and arms move the load: a real but incidental grip, shared between FDS and FDP. Straps take load off the fingers (M3), so a set logged with straps earns no grip credit; one with straps not recorded keeps it and says so.$$, $$reviewed$$),
