  ($$forearm_mappings_v1$$, $$cat-383:forearm.fds$$, $$cat-383$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The fingers hold the bar or handle while the back and arms move the load: a real but incidental grip, shared between FDS and FDP. Straps take load off the fingers (M3), so a set logged with straps earns no grip credit; one with straps not recorded keeps it and says so.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-384:forearm.br$$, $$cat-384$$, $$forearm.br$$, $$elbow.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The elbows bend under load in a row, pulldown or pull-up, and the brachioradialis is an elbow flexor, so it helps move the load through range. Its share changes with hand position (M1), and the back muscles are the target, so it is contributing, never direct.$$, $$reviewed$$),
