  ($$forearm_mappings_v1$$, $$cat-384:forearm.fds$$, $$cat-384$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The fingers hold the bar or handle while the back and arms move the load: a real but incidental grip, shared between FDS and FDP. Straps take load off the fingers (M3), so a set logged with straps earns no grip credit; one with straps not recorded keeps it and says so.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-399:forearm.fdp$$, $$cat-399$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fists hold the rope ends while the shoulders and trunk drive them: an incidental grip, shared between FDS and FDP. Straps do not apply.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-399:forearm.fds$$, $$cat-399$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fists hold the rope ends while the shoulders and trunk drive them: an incidental grip, shared between FDS and FDP. Straps do not apply.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-400:forearm.fdp$$, $$cat-400$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fists hold the rope ends while the shoulders and trunk drive them: an incidental grip, shared between FDS and FDP. Straps do not apply.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-400:forearm.fds$$, $$cat-400$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fists hold the rope ends while the shoulders and trunk drive them: an incidental grip, shared between FDS and FDP. Straps do not apply.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-401:forearm.fdp$$, $$cat-401$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$The bar rolls to the fingertips and is curled back by bending the fingers, so the finger flexors move through range: direct, dynamic work, shared between FDS and FDP. A set where the fingers do not move is not this exercise.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-401:forearm.fds$$, $$cat-401$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$The bar rolls to the fingertips and is curled back by bending the fingers, so the finger flexors move through range: direct, dynamic work, shared between FDS and FDP. A set where the fingers do not move is not this exercise.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-402:forearm.fdp$$, $$cat-402$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Closing the gripper bends the fingers against the spring, so the finger flexors move through range: direct, dynamic work, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-402:forearm.fds$$, $$cat-402$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Closing the gripper bends the fingers against the spring, so the finger flexors move through range: direct, dynamic work, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-403:forearm.fdp$$, $$cat-403$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, false, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps do not apply to a gripper.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-403:forearm.fds$$, $$cat-403$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, false, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps do not apply to a gripper.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-404:forearm.ed$$, $$cat-404$$, $$forearm.ed$$, $$fingers.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Opening the fingers against a band is finger extension, the extensor digitorum's main action, so it is direct. The little- and index-finger extensors join in, and the work is shared between the three.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-404:forearm.edm$$, $$cat-404$$, $$forearm.edm$$, $$little_finger.extension$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$The extensor digiti minimi straightens the little finger alongside the extensor digitorum when all the fingers open; contributing and shared.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-404:forearm.ei$$, $$cat-404$$, $$forearm.ei$$, $$index_finger.extension$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$The extensor indicis straightens the index finger alongside the extensor digitorum when all the fingers open; contributing and shared.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-405:forearm.fdp$$, $$cat-405$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the handle while the wrist or forearm does the work: an incidental grip, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-405:forearm.fds$$, $$cat-405$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the handle while the wrist or forearm does the work: an incidental grip, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-405:forearm.pq$$, $$cat-405$$, $$forearm.pq$$, $$forearm.pronation$$, $$direct$$, $$dynamic$$, $$emg$$, $$shared$$, false, $$Turning the forearm palm-down against a lever is pronation, which the pronator quadratus and pronator teres do together (M5). Shared: nothing here isolates the quadratus.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-405:forearm.pt$$, $$cat-405$$, $$forearm.pt$$, $$forearm.pronation$$, $$direct$$, $$dynamic$$, $$emg$$, $$shared$$, false, $$Turning the forearm palm-down against a lever is pronation, which the pronator teres and pronator quadratus do together. In a lever task the quadratus led at low torque and the teres rose more as torque grew (M5), so the work is shared and not credited to either alone.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-406:forearm.fdp$$, $$cat-406$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the handle while the wrist or forearm does the work: an incidental grip, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-406:forearm.fds$$, $$cat-406$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the handle while the wrist or forearm does the work: an incidental grip, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-406:forearm.supinator$$, $$cat-406$$, $$forearm.supinator$$, $$forearm.supination$$, $$direct$$, $$dynamic$$, $$emg$$, $$shared$$, false, $$Turning the forearm palm-up against a lever is supination. The supinator led at low torque in a lever task, with the biceps rising as torque grew (M5), and torque changes with the elbow angle (M6): with the elbow bent, as this row defines it, the biceps shares the work, so this is not supinator-only.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-406:upper_arm.biceps$$, $$cat-406$$, $$upper_arm.biceps$$, $$forearm.supination$$, $$contributing$$, $$dynamic$$, $$emg$$, $$shared$$, false, $$With the elbow bent the biceps is a strong supinator and joins in as the load grows (M5, M6); it is credited as contributing, as an upper-arm muscle beside the forearm.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-407:forearm.ecrb$$, $$cat-407$$, $$forearm.ecrb$$, $$wrist.radial_deviation$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Tilting the hand toward the thumb side is done by the flexor and extensor on that side together, so each is direct and the work is shared; how the split moves with a slightly flexed or extended wrist is not known, so no split is given.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-407:forearm.ecrl$$, $$cat-407$$, $$forearm.ecrl$$, $$wrist.radial_deviation$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Tilting the hand toward the thumb side is done by the flexor and extensor on that side together, so each is direct and the work is shared; how the split moves with a slightly flexed or extended wrist is not known, so no split is given.$$, $$reviewed$$),
