  ($$forearm_mappings_v1$$, $$cat-408:forearm.fdp$$, $$cat-408$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the handle while the wrist or forearm does the work: an incidental grip, shared between FDS and FDP.$$, $$reviewed$$),
