  ($$forearm_mappings_v1$$, $$cat-409:forearm.fdp$$, $$cat-409$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps would take the load off the fingers, so a strapped set earns no grip credit.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-409:forearm.fds$$, $$cat-409$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$direct$$, $$isometric$$, $$anatomy$$, $$shared$$, true, $$Holding on is the purpose of the set, so the finger flexors are the direct target, working isometrically for the time logged. FDS and FDP share the work; nothing in a whole-hand grip separates them (S3, S8). Straps would take the load off the fingers, so a strapped set earns no grip credit.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-409:forearm.fpl$$, $$cat-409$$, $$forearm.fpl$$, $$thumb.ip_flexion$$, $$contributing$$, $$isometric$$, $$inference$$, $$individual$$, false, $$The thumb closes over the handle, so the long thumb flexor likely helps hold it; how much it is loaded in a handle grip, as opposed to a pinch, is not established, so this stays pending review.$$, $$draft$$),
  ($$forearm_mappings_v1$$, $$cat-410:forearm.fcr$$, $$cat-410$$, $$forearm.fcr$$, $$wrist.flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A wrist curl is built on wrist flexion, the flexor carpi radialis's main action; the wrist moves through range against the load.$$, $$reviewed$$),
