  ($$forearm_mappings_v1$$, $$cat-410:forearm.fds$$, $$cat-410$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or dumbbell while the wrist moves: incidental grip, shared between FDS and FDP. If the bar is let roll to the fingertips the fingers also move, but that is not part of the definition and is not credited.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-410:forearm.pl$$, $$cat-410$$, $$forearm.pl$$, $$wrist.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The palmaris longus is a weak wrist flexor, so it helps rather than leads; it is absent in some people, and its credit means nothing for them.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-411:forearm.ecrb$$, $$cat-411$$, $$forearm.ecrb$$, $$wrist.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A reverse wrist curl is built on wrist extension, one of the extensor carpi radialis brevis's main actions; the wrist moves through range against the load. Nothing in this exercise is known to favour one radial extensor over the other, so the longus and brevis are credited alike.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-411:forearm.ecrl$$, $$cat-411$$, $$forearm.ecrl$$, $$wrist.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A reverse wrist curl is built on wrist extension, one of the extensor carpi radialis longus's main actions; the wrist moves through range against the load. Nothing in this exercise is known to favour one radial extensor over the other, so the longus and brevis are credited alike.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-411:forearm.ecu$$, $$cat-411$$, $$forearm.ecu$$, $$wrist.extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$A reverse wrist curl is built on wrist extension, one of the extensor carpi ulnaris's main actions; the wrist moves through range against the load.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-411:forearm.ed$$, $$cat-411$$, $$forearm.ed$$, $$wrist.extension$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The extensor digitorum assists wrist extension, but its main job is straightening the fingers, which stay closed on the bar; it is contributing, not direct. This is wrist extension, not finger extension.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-411:forearm.fdp$$, $$cat-411$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or handle while the wrist moves: incidental grip, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-411:forearm.fds$$, $$cat-411$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, false, $$The fingers hold the bar or handle while the wrist moves: incidental grip, shared between FDS and FDP.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-412:forearm.fpl$$, $$cat-412$$, $$forearm.fpl$$, $$thumb.ip_flexion$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$Bending the tip of the thumb against a band is the long thumb flexor's own action (the only muscle that bends the thumb's end joint); small-muscle coverage, not a high-volume default.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-413:forearm.epb$$, $$cat-413$$, $$forearm.epb$$, $$thumb.mcp_extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Straightening the thumb at its knuckle against a band is the extensor pollicis brevis's action, shared with the longus, which straightens the tip.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-413:forearm.epl$$, $$cat-413$$, $$forearm.epl$$, $$thumb.ip_extension$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$shared$$, false, $$Straightening the thumb's tip against a band is the extensor pollicis longus's action; its knuckle is straightened by the brevis at the same time, so the work is shared between them.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-414:forearm.apl$$, $$cat-414$$, $$forearm.apl$$, $$thumb.cmc_abduction$$, $$direct$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$Moving the thumb away from the index finger at its base against a band is thumb abduction, the abductor pollicis longus's action. The short abductor in the hand also works, but hand muscles are not forearm muscles and are not credited here.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-41:forearm.fdp$$, $$cat-41$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The fingers hold the bar, dumbbells or handle while the hips, legs or upper back move the load: a real but incidental grip, shared between FDS and FDP. Straps take load off the fingers (M3), so a set logged with straps earns no grip credit; one with straps not recorded keeps it and says so.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-41:forearm.fds$$, $$cat-41$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The fingers hold the bar, dumbbells or handle while the hips, legs or upper back move the load: a real but incidental grip, shared between FDS and FDP. Straps take load off the fingers (M3), so a set logged with straps earns no grip credit; one with straps not recorded keeps it and says so.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-42:forearm.fdp$$, $$cat-42$$, $$forearm.fdp$$, $$fingers.dip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The fingers hold the bar, dumbbells or handle while the hips, legs or upper back move the load: a real but incidental grip, shared between FDS and FDP. Straps take load off the fingers (M3), so a set logged with straps earns no grip credit; one with straps not recorded keeps it and says so.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-42:forearm.fds$$, $$cat-42$$, $$forearm.fds$$, $$fingers.pip_flexion$$, $$incidental$$, $$isometric$$, $$inference$$, $$shared$$, true, $$The fingers hold the bar, dumbbells or handle while the hips, legs or upper back move the load: a real but incidental grip, shared between FDS and FDP. Straps take load off the fingers (M3), so a set logged with straps earns no grip credit; one with straps not recorded keeps it and says so.$$, $$reviewed$$),
  ($$forearm_mappings_v1$$, $$cat-43:forearm.br$$, $$cat-43$$, $$forearm.br$$, $$elbow.flexion$$, $$contributing$$, $$dynamic$$, $$anatomy$$, $$individual$$, false, $$The elbows bend under load in a row, pulldown or pull-up, and the brachioradialis is an elbow flexor, so it helps move the load through range. Its share changes with hand position (M1), and the back muscles are the target, so it is contributing, never direct.$$, $$reviewed$$),
